"""Fill only 2025 exit-bar gaps generated by the predeclared round2 variants."""
from __future__ import annotations

import argparse
import hashlib
import json
import socket
import time
from pathlib import Path

from logic_b.collect import BaoStockClient, fetch_5m
from logic_b.replay import replay
from luna_goal_round2 import VARIANTS
from luna_goal_train import _load_2025


def _missing_exits(dataset: dict, config: dict) -> set[tuple[str, str]]:
    gaps = set()
    for variant in VARIANTS:
        cfg = json.loads(json.dumps(config))
        cfg["baseline"].update(variant["params"])
        result = replay(dataset, cfg)
        gaps.update((row["symbol"], row["day"]) for row in result["orders"]
                    if row.get("side") == "SELL" and row.get("reason") == "MISSING_5M_BARS")
    return {(code, day) for code, day in gaps if day.startswith("2025-")}


def run(source: Path, destination: Path, config_path: Path, cache: Path,
        max_passes: int = 6, delay: float = 0.2, socket_timeout: float = 15) -> dict:
    socket.setdefaulttimeout(socket_timeout)
    dataset, source_sha = _load_2025(source)
    config = json.loads(config_path.read_text(encoding="utf-8"))
    days_by_date = {day["date"]: day for day in dataset["days"]}
    total_new = total_reused = total_failures = 0
    passes = []
    attempted = set()
    for pass_number in range(1, max_passes + 1):
        gaps = _missing_exits(dataset, config)
        gaps = {(code, day) for code, day in gaps
                if not (days_by_date[day].get("bars_5m") or {}).get(code)
                and (code, day) not in attempted}
        if not gaps:
            break
        new_count = reused_count = failures = 0
        with BaoStockClient() as client:
            for code, day in sorted(gaps, key=lambda x: (x[1], x[0])):
                attempted.add((code, day))
                try:
                    result = fetch_5m(code, day, cache, client)
                    if result.get("cache_hit"):
                        reused_count += 1
                    else:
                        new_count += 1
                    if result.get("bars"):
                        days_by_date[day].setdefault("bars_5m", {})[code] = result["bars"]
                except Exception:
                    failures += 1
                if (new_count + reused_count + failures) % 10 == 0:
                    print(f"round2 exit bars: pass {pass_number}, "
                          f"{new_count + reused_count + failures}/{len(gaps)} completed", flush=True)
                if delay > 0:
                    time.sleep(delay)
        total_new += new_count
        total_reused += reused_count
        total_failures += failures
        remaining = _missing_exits(dataset, config)
        passes.append({"pass": pass_number, "requested_symbol_days": len(gaps),
                       "new_queries": new_count, "cache_reuses": reused_count,
                       "failed_requests": failures, "remaining_sell_bar_gaps": len(remaining)})
        if failures and new_count + reused_count == 0:
            break
    payload = json.dumps(dataset, ensure_ascii=False, sort_keys=True, indent=2,
                         allow_nan=False).encode("utf-8")
    destination.parent.mkdir(parents=True, exist_ok=True)
    destination.write_bytes(payload)
    remaining = _missing_exits(dataset, config)
    summary = {"classification": "PRIVATE_2025_BAOSTOCK_EXIT_BAR_MATERIALIZATION",
        "source_snapshot_sha256": source_sha,
        "expanded_snapshot_sha256": hashlib.sha256(payload).hexdigest(),
        "date_window": ["2025-01-01", "2025-12-31"],
        "provider": "BaoStock", "requested_scope": "sell-side missing 5m bars from five predeclared variants",
        "new_queries": total_new, "cache_reuses": total_reused,
        "failed_requests": total_failures, "passes": passes,
        "remaining_sell_symbol_days_missing": len(remaining),
        "result": "COMPLETE" if not remaining else "PARTIAL_DATA_GAPS_REMAIN"}
    summary_path = destination.with_name("exit_materialization_summary.json")
    summary_path.write_text(json.dumps(summary, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    return summary


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--source", type=Path, required=True)
    parser.add_argument("--out", type=Path, required=True)
    parser.add_argument("--config", type=Path, default=Path("config/goal_2025_2026.json"))
    parser.add_argument("--cache", type=Path, default=Path("data/raw"))
    parser.add_argument("--max-passes", type=int, default=6)
    parser.add_argument("--delay", type=float, default=0.2)
    parser.add_argument("--socket-timeout", type=float, default=15)
    args = parser.parse_args()
    print(json.dumps(run(args.source, args.out, args.config, args.cache,
                         args.max_passes, args.delay, args.socket_timeout), ensure_ascii=False, indent=2))


if __name__ == "__main__":
    main()
